-- Tikkit initial schema (issue #6). Target: PostgreSQL 16.
--
-- Conventions (see docs/database.md):
-- * Enumerations are `text` columns with CHECK constraints rather than
--   PostgreSQL ENUM types, so later migrations can add or retire values
--   with a plain ALTER TABLE ... DROP/ADD CONSTRAINT inside a transaction.
--   Values are the stable snake_case machine identifiers used by the API.
-- * Primary keys are UUIDs (normally UUID v7 generated by the API;
--   gen_random_uuid() is only a fallback default). IDs never change.
-- * All timestamps are timestamptz and are written/read as UTC.
-- * Invariants that must hold regardless of application bugs or concurrent
--   writers are enforced here too (unique partial indexes, triggers that take
--   row locks, deferred constraint triggers). Trigger errors use SQLSTATE
--   check_violation (23514) or restrict_violation (23001) and name a
--   CONSTRAINT so the API can map them to stable error codes.
-- * Never edit this file after it has been released; add a new migration.

-- ---------------------------------------------------------------------------
-- Shared helpers
-- ---------------------------------------------------------------------------

CREATE FUNCTION tikkit_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- Rejects UPDATE, DELETE and TRUNCATE on append-only tables.
CREATE FUNCTION tikkit_reject_modification() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% is append-only; % is not allowed', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'restrict_violation',
              CONSTRAINT = TG_TABLE_NAME || '_append_only';
END;
$$;

-- ---------------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------------

CREATE TABLE accounts (
    id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    -- As entered (trimmed); shown in the UI and audit history.
    username            text        NOT NULL CHECK (char_length(username) BETWEEN 1 AND 64),
    -- NFKC + lowercase form computed in Rust; the uniqueness key for login.
    username_normalized text        NOT NULL CHECK (username_normalized ~ '^[a-z0-9._-]{3,32}$'),
    -- Contact/notification address only. Deliberately NOT unique: separate
    -- accounts (e.g. an Admin and an operational account) may share it.
    email               text        NOT NULL CHECK (char_length(email) BETWEEN 3 AND 254 AND position('@' IN email) > 1),
    display_name        text        NOT NULL CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 100),
    role                text        NOT NULL DEFAULT 'user'
                                    CHECK (role IN ('user', 'operator', 'specialist', 'team_lead', 'admin')),
    -- Expertise/field designation shown for Specialists. Grants no access.
    specialization      text        CHECK (specialization IS NULL OR char_length(btrim(specialization)) BETWEEN 1 AND 100),
    language            text        NOT NULL DEFAULT 'en' CHECK (language IN ('en', 'de')),
    password_hash       text        NOT NULL CHECK (char_length(password_hash) > 0),
    status              text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'deactivated')),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    deactivated_at      timestamptz,
    CONSTRAINT accounts_username_normalized_key UNIQUE (username_normalized),
    CONSTRAINT accounts_deactivated_at_matches_status
        CHECK ((status = 'deactivated') = (deactivated_at IS NOT NULL))
);

-- Non-unique lookup index (e.g. for notifications); never used to merge accounts.
CREATE INDEX accounts_email_idx ON accounts (lower(email));
CREATE INDEX accounts_role_idx ON accounts (role) WHERE status = 'active';

CREATE TRIGGER accounts_set_updated_at
    BEFORE UPDATE ON accounts
    FOR EACH ROW EXECUTE FUNCTION tikkit_set_updated_at();

-- ---------------------------------------------------------------------------
-- Organization settings (exactly one row; one organization per deployment)
-- ---------------------------------------------------------------------------

CREATE TABLE organization_settings (
    id                                    boolean     PRIMARY KEY DEFAULT true CHECK (id),
    bootstrap_completed_at                timestamptz,
    bootstrap_admin_account_id            uuid        REFERENCES accounts (id),
    default_language                      text        NOT NULL DEFAULT 'en' CHECK (default_language IN ('en', 'de')),
    allow_requester_skip_ai               boolean     NOT NULL DEFAULT false,
    reopen_closed_tickets_enabled         boolean     NOT NULL DEFAULT false,
    cancellation_policy                   text        NOT NULL DEFAULT 'anytime_while_open'
                                                      CHECK (cancellation_policy IN ('anytime_while_open', 'before_work_starts', 'disabled')),
    resolution_confirmation_timeout_hours integer     NOT NULL DEFAULT 168
        CONSTRAINT organization_settings_timeout_positive CHECK (resolution_confirmation_timeout_hours > 0),
    created_at                            timestamptz NOT NULL DEFAULT now(),
    updated_at                            timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT organization_settings_bootstrap_complete
        CHECK ((bootstrap_completed_at IS NULL) = (bootstrap_admin_account_id IS NULL))
);

INSERT INTO organization_settings DEFAULT VALUES;

-- First setup happens exactly once: once recorded, bootstrap cannot be undone
-- or re-run, and the singleton row cannot be deleted.
CREATE FUNCTION tikkit_guard_organization_settings() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'organization_settings row cannot be deleted'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'organization_settings_singleton';
    END IF;
    IF OLD.bootstrap_completed_at IS NOT NULL
       AND (NEW.bootstrap_completed_at IS DISTINCT FROM OLD.bootstrap_completed_at
            OR NEW.bootstrap_admin_account_id IS DISTINCT FROM OLD.bootstrap_admin_account_id) THEN
        RAISE EXCEPTION 'first setup has already been completed'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'organization_settings_bootstrap_once';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER organization_settings_guard
    BEFORE UPDATE OR DELETE ON organization_settings
    FOR EACH ROW EXECUTE FUNCTION tikkit_guard_organization_settings();

CREATE TRIGGER organization_settings_no_truncate
    BEFORE TRUNCATE ON organization_settings
    FOR EACH STATEMENT EXECUTE FUNCTION tikkit_reject_modification();

CREATE TRIGGER organization_settings_set_updated_at
    BEFORE UPDATE ON organization_settings
    FOR EACH ROW EXECUTE FUNCTION tikkit_set_updated_at();

-- ---------------------------------------------------------------------------
-- Teams and memberships
-- ---------------------------------------------------------------------------

CREATE TABLE teams (
    id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text        NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
    status      text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    archived_at timestamptz,
    CONSTRAINT teams_archived_at_matches_status
        CHECK ((status = 'archived') = (archived_at IS NOT NULL))
);

-- Names are unique among active teams (case-insensitive); archived names may be reused.
CREATE UNIQUE INDEX teams_active_name_key ON teams (lower(name)) WHERE status = 'active';

CREATE TRIGGER teams_set_updated_at
    BEFORE UPDATE ON teams
    FOR EACH ROW EXECUTE FUNCTION tikkit_set_updated_at();

-- Membership history. A row is "current" while ended_at IS NULL. Rows are
-- never deleted or rewritten; the only permitted update is ending a current
-- row. Leadership is a flag on the membership, so a lead always belongs to
-- the team they lead. Changing leadership = end the old row(s) and insert new
-- row(s) in one transaction.
CREATE TABLE team_memberships (
    id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    team_id    uuid        NOT NULL REFERENCES teams (id),
    account_id uuid        NOT NULL REFERENCES accounts (id),
    is_lead    boolean     NOT NULL DEFAULT false,
    started_at timestamptz NOT NULL DEFAULT now(),
    ended_at   timestamptz,
    CONSTRAINT team_memberships_period CHECK (ended_at IS NULL OR ended_at >= started_at)
);

-- At most one current team per account (and therefore at most one leadership).
CREATE UNIQUE INDEX team_memberships_one_current_per_account
    ON team_memberships (account_id) WHERE ended_at IS NULL;
-- At most one current lead per team (no co-leads, even under concurrency).
CREATE UNIQUE INDEX team_memberships_one_current_lead_per_team
    ON team_memberships (team_id) WHERE ended_at IS NULL AND is_lead;
CREATE INDEX team_memberships_current_by_team
    ON team_memberships (team_id) WHERE ended_at IS NULL;
CREATE INDEX team_memberships_history_by_account
    ON team_memberships (account_id, started_at);

CREATE FUNCTION tikkit_guard_team_membership() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    account_role   text;
    account_status text;
    team_status    text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'team membership history cannot be deleted'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'team_memberships_history';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF OLD.ended_at IS NOT NULL
           OR NEW.ended_at IS NULL
           OR NEW.id IS DISTINCT FROM OLD.id
           OR NEW.team_id IS DISTINCT FROM OLD.team_id
           OR NEW.account_id IS DISTINCT FROM OLD.account_id
           OR NEW.is_lead IS DISTINCT FROM OLD.is_lead
           OR NEW.started_at IS DISTINCT FROM OLD.started_at THEN
            RAISE EXCEPTION 'team memberships can only be ended; insert a new row to change membership or leadership'
                USING ERRCODE = 'restrict_violation', CONSTRAINT = 'team_memberships_history';
        END IF;
        RETURN NEW;
    END IF;

    -- INSERT. Historical (already ended) rows skip current-state checks.
    IF NEW.ended_at IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- Share-lock the account and team so concurrent role/status changes or
    -- team archival serialize with this insert.
    SELECT role, status INTO account_role, account_status
        FROM accounts WHERE id = NEW.account_id FOR SHARE;
    SELECT status INTO team_status
        FROM teams WHERE id = NEW.team_id FOR SHARE;

    IF account_role = 'admin' THEN
        RAISE EXCEPTION 'admin accounts cannot be team members or leads'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_no_admin';
    END IF;
    IF account_status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'only active accounts can join a team'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_active_account';
    END IF;
    IF team_status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'archived teams cannot gain members'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_active_team';
    END IF;
    IF NEW.is_lead AND account_role <> 'team_lead' THEN
        RAISE EXCEPTION 'a team lead must have the team_lead role'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_lead_role';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER team_memberships_guard
    BEFORE INSERT OR UPDATE OR DELETE ON team_memberships
    FOR EACH ROW EXECUTE FUNCTION tikkit_guard_team_membership();

CREATE TRIGGER team_memberships_no_truncate
    BEFORE TRUNCATE ON team_memberships
    FOR EACH STATEMENT EXECUTE FUNCTION tikkit_reject_modification();

-- Checked at COMMIT (deferred): every active team has exactly one current
-- lead, and archived teams have no current members. This makes "create team
-- + appoint lead" and "replace lead" atomic multi-statement transactions.
CREATE FUNCTION tikkit_check_team_leadership() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    target_team  uuid;
    team_status  text;
    lead_count   integer;
    member_count integer;
BEGIN
    IF TG_TABLE_NAME = 'teams' THEN
        target_team := NEW.id;
    ELSE
        target_team := NEW.team_id;
    END IF;

    SELECT status INTO team_status FROM teams WHERE id = target_team;
    SELECT count(*) FILTER (WHERE is_lead), count(*)
        INTO lead_count, member_count
        FROM team_memberships
        WHERE team_id = target_team AND ended_at IS NULL;

    IF team_status = 'active' AND lead_count <> 1 THEN
        RAISE EXCEPTION 'active team % must have exactly one current lead (found %)', target_team, lead_count
            USING ERRCODE = 'check_violation', CONSTRAINT = 'teams_exactly_one_lead';
    END IF;
    IF team_status = 'archived' AND member_count > 0 THEN
        RAISE EXCEPTION 'archived team % still has % current member(s)', target_team, member_count
            USING ERRCODE = 'check_violation', CONSTRAINT = 'teams_archived_without_members';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER teams_leadership_check
    AFTER INSERT OR UPDATE ON teams
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION tikkit_check_team_leadership();

CREATE CONSTRAINT TRIGGER team_memberships_leadership_check
    AFTER INSERT OR UPDATE ON team_memberships
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION tikkit_check_team_leadership();

-- Role/status changes must not break membership invariants.
CREATE FUNCTION tikkit_guard_account_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id THEN
        RAISE EXCEPTION 'account ids are immutable'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'accounts_id_immutable';
    END IF;
    IF NEW.role = 'admin' AND OLD.role <> 'admin' AND EXISTS (
        SELECT 1 FROM team_memberships WHERE account_id = NEW.id AND ended_at IS NULL
    ) THEN
        RAISE EXCEPTION 'end the team membership before granting the admin role'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_no_admin';
    END IF;
    IF OLD.role = 'team_lead' AND NEW.role <> 'team_lead' AND EXISTS (
        SELECT 1 FROM team_memberships WHERE account_id = NEW.id AND ended_at IS NULL AND is_lead
    ) THEN
        RAISE EXCEPTION 'replace this account as team lead before changing its role'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_lead_role';
    END IF;
    IF NEW.status = 'deactivated' AND OLD.status <> 'deactivated' AND EXISTS (
        SELECT 1 FROM team_memberships WHERE account_id = NEW.id AND ended_at IS NULL AND is_lead
    ) THEN
        RAISE EXCEPTION 'replace this account as team lead before deactivating it'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'team_memberships_lead_active';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER accounts_guard
    BEFORE UPDATE ON accounts
    FOR EACH ROW EXECUTE FUNCTION tikkit_guard_account_update();

-- ---------------------------------------------------------------------------
-- Categories and priorities (Admin managed; archived rows stay for history)
-- ---------------------------------------------------------------------------

CREATE TABLE categories (
    id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text        NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
    -- "Skip AI automatically": tickets in this category make zero provider calls.
    skip_ai     boolean     NOT NULL DEFAULT false,
    sort_order  integer     NOT NULL DEFAULT 0,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    archived_at timestamptz
);

CREATE UNIQUE INDEX categories_active_name_key ON categories (lower(name)) WHERE archived_at IS NULL;
CREATE INDEX categories_active_order ON categories (sort_order, id) WHERE archived_at IS NULL;

CREATE TRIGGER categories_set_updated_at
    BEFORE UPDATE ON categories
    FOR EACH ROW EXECUTE FUNCTION tikkit_set_updated_at();

CREATE TABLE priorities (
    id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text        NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
    -- Lower sort_order is shown first.
    sort_order  integer     NOT NULL DEFAULT 0,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    archived_at timestamptz
);

CREATE UNIQUE INDEX priorities_active_name_key ON priorities (lower(name)) WHERE archived_at IS NULL;
CREATE INDEX priorities_active_order ON priorities (sort_order, id) WHERE archived_at IS NULL;

CREATE TRIGGER priorities_set_updated_at
    BEFORE UPDATE ON priorities
    FOR EACH ROW EXECUTE FUNCTION tikkit_set_updated_at();

-- ---------------------------------------------------------------------------
-- Tickets
-- ---------------------------------------------------------------------------

-- Status is the current lifecycle state; resolution_kind records how a
-- closed ticket was closed. An AI-solved ticket is
--   status = 'closed' AND resolution_kind = 'ai_confirmed'
-- and is final (see tikkit_guard_ticket_update). Human closures are
-- 'requester_confirmed' (requester confirmed a staff proposal) or
-- 'auto_closed_timeout' (confirmation timeout elapsed), kept distinct for
-- reporting. Cancellation is its own status, never a resolution.
CREATE TABLE tickets (
    id                    uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Stable, human-facing reference number (e.g. shown as #1042).
    reference             bigint      GENERATED ALWAYS AS IDENTITY,
    requester_account_id  uuid        NOT NULL REFERENCES accounts (id),
    category_id           uuid        REFERENCES categories (id),
    subject               text        CHECK (subject IS NULL OR char_length(subject) <= 200),
    description           text        CHECK (description IS NULL OR char_length(description) <= 20000),
    -- The requester's original choice; the effective priority is priority_id.
    requested_priority_id uuid        REFERENCES priorities (id),
    priority_id           uuid        REFERENCES priorities (id),
    -- Frozen intake at submission: category/priority ids and names, subject,
    -- description, visible conditional answers, screenshot ids.
    intake_snapshot       jsonb       CHECK (intake_snapshot IS NULL OR jsonb_typeof(intake_snapshot) = 'object'),
    status                text        NOT NULL DEFAULT 'draft'
                                      CHECK (status IN ('draft', 'ai_processing', 'awaiting_ai_decision', 'queued',
                                                        'in_progress', 'waiting_for_requester',
                                                        'awaiting_confirmation', 'closed', 'cancelled')),
    resolution_kind       text        CHECK (resolution_kind IN ('ai_confirmed', 'requester_confirmed', 'auto_closed_timeout')),
    -- NULL team = shared general queue.
    team_id               uuid        REFERENCES teams (id),
    assignee_account_id   uuid        REFERENCES accounts (id),
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),
    submitted_at          timestamptz,
    closed_at             timestamptz,
    cancelled_at          timestamptz,
    CONSTRAINT tickets_reference_key UNIQUE (reference),
    CONSTRAINT tickets_submitted_at_matches_status
        CHECK ((status = 'draft') = (submitted_at IS NULL)),
    CONSTRAINT tickets_submitted_intake_complete
        CHECK (status = 'draft' OR (category_id IS NOT NULL AND subject IS NOT NULL AND description IS NOT NULL
                                    AND requested_priority_id IS NOT NULL AND priority_id IS NOT NULL
                                    AND intake_snapshot IS NOT NULL)),
    CONSTRAINT tickets_closed_has_resolution
        CHECK ((status = 'closed') = (resolution_kind IS NOT NULL)
               AND (status = 'closed') = (closed_at IS NOT NULL)),
    CONSTRAINT tickets_cancelled_at_matches_status
        CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL)),
    -- Tickets before human handoff (and AI-solved ones) never have a team or assignee.
    CONSTRAINT tickets_pre_handoff_unrouted
        CHECK (status NOT IN ('draft', 'ai_processing', 'awaiting_ai_decision')
               OR (team_id IS NULL AND assignee_account_id IS NULL)),
    CONSTRAINT tickets_ai_solved_unrouted
        CHECK (resolution_kind IS DISTINCT FROM 'ai_confirmed'
               OR (team_id IS NULL AND assignee_account_id IS NULL)),
    CONSTRAINT tickets_assignee_requires_team
        CHECK (assignee_account_id IS NULL OR team_id IS NOT NULL),
    -- Self-handling: the requester can never be the assignee.
    CONSTRAINT tickets_assignee_not_requester
        CHECK (assignee_account_id IS DISTINCT FROM requester_account_id)
);

CREATE INDEX tickets_requester_idx ON tickets (requester_account_id, created_at DESC, id);
CREATE INDEX tickets_general_queue_idx ON tickets (submitted_at, id)
    WHERE team_id IS NULL AND status NOT IN ('draft', 'ai_processing', 'awaiting_ai_decision', 'closed', 'cancelled');
CREATE INDEX tickets_team_idx ON tickets (team_id, status, submitted_at) WHERE team_id IS NOT NULL;
CREATE INDEX tickets_assignee_idx ON tickets (assignee_account_id, status) WHERE assignee_account_id IS NOT NULL;
CREATE INDEX tickets_status_idx ON tickets (status, submitted_at);
CREATE INDEX tickets_category_idx ON tickets (category_id);
CREATE INDEX tickets_requested_priority_idx ON tickets (requested_priority_id);
CREATE INDEX tickets_priority_idx ON tickets (priority_id);

CREATE TRIGGER tickets_set_updated_at
    BEFORE UPDATE ON tickets
    FOR EACH ROW EXECUTE FUNCTION tikkit_set_updated_at();

-- Identity and submitted intake are immutable; AI-solved tickets are final.
CREATE FUNCTION tikkit_guard_ticket_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.status = 'closed' AND OLD.resolution_kind = 'ai_confirmed' THEN
        RAISE EXCEPTION 'AI-solved tickets are final and read-only'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'tickets_ai_solved_final';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.reference IS DISTINCT FROM OLD.reference
       OR NEW.requester_account_id IS DISTINCT FROM OLD.requester_account_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'ticket identity and requester are immutable'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'tickets_identity_immutable';
    END IF;
    IF OLD.submitted_at IS NOT NULL AND (
           NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
        OR NEW.subject IS DISTINCT FROM OLD.subject
        OR NEW.description IS DISTINCT FROM OLD.description
        OR NEW.requested_priority_id IS DISTINCT FROM OLD.requested_priority_id
        OR NEW.intake_snapshot IS DISTINCT FROM OLD.intake_snapshot) THEN
        RAISE EXCEPTION 'submitted intake is frozen'
            USING ERRCODE = 'restrict_violation', CONSTRAINT = 'tickets_intake_frozen';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER tickets_guard
    BEFORE UPDATE ON tickets
    FOR EACH ROW EXECUTE FUNCTION tikkit_guard_ticket_update();

-- The assignee must be a current member of the ticket's team (Admins can
-- never be members, so they can never be assignees). The membership row is
-- share-locked so a concurrent removal serializes with the assignment.
CREATE FUNCTION tikkit_check_ticket_assignee() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    -- A missing team is reported by tickets_assignee_requires_team.
    IF NEW.assignee_account_id IS NULL OR NEW.team_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE'
       AND NEW.assignee_account_id IS NOT DISTINCT FROM OLD.assignee_account_id
       AND NEW.team_id IS NOT DISTINCT FROM OLD.team_id THEN
        RETURN NEW;
    END IF;
    PERFORM 1 FROM team_memberships
        WHERE account_id = NEW.assignee_account_id
          AND team_id = NEW.team_id
          AND ended_at IS NULL
        FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'the assignee must be a current member of the ticket''s team'
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tickets_assignee_team_member';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER tickets_assignee_check
    BEFORE INSERT OR UPDATE OF assignee_account_id, team_id ON tickets
    FOR EACH ROW EXECUTE FUNCTION tikkit_check_ticket_assignee();

-- ---------------------------------------------------------------------------
-- Messages and screenshot metadata
-- ---------------------------------------------------------------------------

CREATE TABLE ticket_messages (
    id                uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    ticket_id         uuid        NOT NULL REFERENCES tickets (id),
    author_account_id uuid        NOT NULL REFERENCES accounts (id),
    -- 'internal' notes are staff-only and never reach requesters.
    visibility        text        NOT NULL CHECK (visibility IN ('public', 'internal')),
    body              text        NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 20000),
    created_at        timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ticket_messages_id_ticket_key UNIQUE (id, ticket_id)
);

CREATE INDEX ticket_messages_ticket_idx ON ticket_messages (ticket_id, created_at, id);
CREATE INDEX ticket_messages_author_idx ON ticket_messages (author_account_id);

-- Earlier messages are never rewritten.
CREATE TRIGGER ticket_messages_append_only
    BEFORE UPDATE OR DELETE ON ticket_messages
    FOR EACH ROW EXECUTE FUNCTION tikkit_reject_modification();

CREATE TRIGGER ticket_messages_no_truncate
    BEFORE TRUNCATE ON ticket_messages
    FOR EACH STATEMENT EXECUTE FUNCTION tikkit_reject_modification();

-- Closed (including AI-solved), cancelled and draft tickets accept no messages;
-- closed and cancelled tickets accept no screenshots. The ticket row is
-- share-locked so a concurrent close/cancel serializes with the insert.
CREATE FUNCTION tikkit_check_ticket_open_for_content() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    ticket_status text;
BEGIN
    SELECT status INTO ticket_status FROM tickets WHERE id = NEW.ticket_id FOR SHARE;
    IF ticket_status IN ('closed', 'cancelled')
       OR (TG_TABLE_NAME = 'ticket_messages' AND ticket_status = 'draft') THEN
        RAISE EXCEPTION 'ticket in status % does not accept new content', ticket_status
            USING ERRCODE = 'check_violation', CONSTRAINT = TG_TABLE_NAME || '_ticket_open';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER ticket_messages_ticket_open
    BEFORE INSERT ON ticket_messages
    FOR EACH ROW EXECUTE FUNCTION tikkit_check_ticket_open_for_content();

-- Screenshot metadata. File bytes live in the private screenshot volume
-- under storage_key. message_id NULL = part of the (draft) intake.
CREATE TABLE attachments (
    id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    ticket_id           uuid        NOT NULL REFERENCES tickets (id),
    message_id          uuid,
    uploader_account_id uuid        NOT NULL REFERENCES accounts (id),
    storage_key         text        NOT NULL CHECK (storage_key ~ '^[A-Za-z0-9/_-]{1,200}$'),
    content_type        text        NOT NULL CHECK (content_type IN ('image/png', 'image/jpeg', 'image/webp')),
    byte_size           bigint      NOT NULL CHECK (byte_size > 0),
    width               integer     NOT NULL CHECK (width > 0),
    height              integer     NOT NULL CHECK (height > 0),
    sha256              text        NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    original_filename   text        CHECK (original_filename IS NULL OR char_length(original_filename) BETWEEN 1 AND 255),
    created_at          timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT attachments_storage_key_key UNIQUE (storage_key),
    -- A message attachment must belong to a message of the same ticket.
    CONSTRAINT attachments_message_same_ticket
        FOREIGN KEY (message_id, ticket_id) REFERENCES ticket_messages (id, ticket_id)
);

CREATE INDEX attachments_ticket_idx ON attachments (ticket_id, created_at);
CREATE INDEX attachments_message_idx ON attachments (message_id) WHERE message_id IS NOT NULL;
CREATE INDEX attachments_uploader_idx ON attachments (uploader_account_id);

CREATE TRIGGER attachments_ticket_open
    BEFORE INSERT ON attachments
    FOR EACH ROW EXECUTE FUNCTION tikkit_check_ticket_open_for_content();

-- ---------------------------------------------------------------------------
-- Immutable history
-- ---------------------------------------------------------------------------

-- State transitions and other ticket events with provenance. Append-only.
CREATE TABLE ticket_events (
    id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    ticket_id        uuid        NOT NULL REFERENCES tickets (id),
    actor_account_id uuid        REFERENCES accounts (id),
    -- 'user' = acting as the requester, 'staff' = staff/Admin handling,
    -- 'system' = background job (no account).
    actor_kind       text        NOT NULL CHECK (actor_kind IN ('user', 'staff', 'system')),
    event_type       text        NOT NULL CHECK (event_type ~ '^[a-z][a-z0-9_.]{0,63}$'),
    from_status      text        CHECK (from_status IN ('draft', 'ai_processing', 'awaiting_ai_decision', 'queued',
                                                        'in_progress', 'waiting_for_requester',
                                                        'awaiting_confirmation', 'closed', 'cancelled')),
    to_status        text        CHECK (to_status IN ('draft', 'ai_processing', 'awaiting_ai_decision', 'queued',
                                                      'in_progress', 'waiting_for_requester',
                                                      'awaiting_confirmation', 'closed', 'cancelled')),
    data             jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(data) = 'object'),
    created_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ticket_events_actor_matches_kind
        CHECK ((actor_kind = 'system') = (actor_account_id IS NULL))
);

CREATE INDEX ticket_events_ticket_idx ON ticket_events (ticket_id, created_at, id);
CREATE INDEX ticket_events_type_idx ON ticket_events (event_type, created_at);
CREATE INDEX ticket_events_actor_idx ON ticket_events (actor_account_id) WHERE actor_account_id IS NOT NULL;

CREATE TRIGGER ticket_events_append_only
    BEFORE UPDATE OR DELETE ON ticket_events
    FOR EACH ROW EXECUTE FUNCTION tikkit_reject_modification();

CREATE TRIGGER ticket_events_no_truncate
    BEFORE TRUNCATE ON ticket_events
    FOR EACH STATEMENT EXECUTE FUNCTION tikkit_reject_modification();

-- Attributable audit trail. Append-only; metadata must never contain secrets.
CREATE TABLE audit_events (
    id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    occurred_at      timestamptz NOT NULL DEFAULT now(),
    actor_account_id uuid        REFERENCES accounts (id),
    -- 'account' = a signed-in account, 'system' = background job,
    -- 'anonymous' = unauthenticated request (e.g. failed login).
    actor_kind       text        NOT NULL CHECK (actor_kind IN ('account', 'system', 'anonymous')),
    action           text        NOT NULL CHECK (action ~ '^[a-z][a-z0-9_.]{0,63}$'),
    target_type      text        CHECK (target_type IS NULL OR target_type ~ '^[a-z][a-z0-9_]{0,63}$'),
    target_id        text        CHECK (target_id IS NULL OR char_length(target_id) BETWEEN 1 AND 128),
    metadata         jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(metadata) = 'object'),
    request_id       text        CHECK (request_id IS NULL OR char_length(request_id) BETWEEN 1 AND 128),
    CONSTRAINT audit_events_actor_matches_kind
        CHECK ((actor_kind = 'account') = (actor_account_id IS NOT NULL))
);

CREATE INDEX audit_events_occurred_idx ON audit_events (occurred_at DESC, id);
CREATE INDEX audit_events_actor_idx ON audit_events (actor_account_id, occurred_at DESC) WHERE actor_account_id IS NOT NULL;
CREATE INDEX audit_events_target_idx ON audit_events (target_type, target_id, occurred_at DESC) WHERE target_type IS NOT NULL;
CREATE INDEX audit_events_action_idx ON audit_events (action, occurred_at DESC);

CREATE TRIGGER audit_events_append_only
    BEFORE UPDATE OR DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION tikkit_reject_modification();

CREATE TRIGGER audit_events_no_truncate
    BEFORE TRUNCATE ON audit_events
    FOR EACH STATEMENT EXECUTE FUNCTION tikkit_reject_modification();
